import{_ as s,o as n,c as e,a0 as l}from"./chunks/framework.DqMqoJl9.js";const p="/assets/2-array_20210128143226.hfiBfX-g.png",o="/assets/2-array_20210128143244.Bdka6wjX.png",r="/assets/2-array_20210128144159.CwYcaOv1.png",_=JSON.parse('{"title":"数组","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/2-array.md","filePath":"algorithm/2-array.md","lastUpdated":1791573371000}'),t={name:"algorithm/2-array.md"};function c(i,a,d,h,b,u){return n(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="数组" tabindex="-1">数组 <a class="header-anchor" href="#数组" aria-label="Permalink to &quot;数组&quot;">​</a></h1><h2 id="_1-概念" tabindex="-1">1 概念 <a class="header-anchor" href="#_1-概念" aria-label="Permalink to &quot;1 概念&quot;">​</a></h2><p>在每一种编程语言中，基本都会有数组这种数据类型。不过，它不仅仅是一种编程语言中的数据类型，还是一种最基础的数据结构</p><blockquote><p>数组（Array）是一种线性表数据结构。它用一组连续的内存空间，来存储一组具有相同类型的数据</p></blockquote><p>这个定义里有几个关键词，理解了这几个关键词，就能彻底掌握数组的概念</p><h3 id="_1-1-线性表" tabindex="-1">1.1 线性表 <a class="header-anchor" href="#_1-1-线性表" aria-label="Permalink to &quot;1.1 线性表&quot;">​</a></h3><p>第一是线性表（Linear List）。顾名思义，线性表就是数据排成像一条线一样的结构。每个线性表上的数据最多只有前和后两个方向。其实除了数组，链表、队列、栈等也是线性表结构。</p><p><img src="'+p+'" alt=""></p><p>而与它相对立的概念是非线性表，比如二叉树、堆、图等。之所以叫非线性，是因为，在非线性表中，数据之间并不是简单的前后关系。</p><p><img src="'+o+'" alt=""></p><h3 id="_1-2-连续的内存空间和相同类型的数据" tabindex="-1">1.2 连续的内存空间和相同类型的数据 <a class="header-anchor" href="#_1-2-连续的内存空间和相同类型的数据" aria-label="Permalink to &quot;1.2 连续的内存空间和相同类型的数据&quot;">​</a></h3><p>连续的内存空间和相同类型的数据。正是因为这两个限制，它才有了一个堪称“杀手锏”的特性：“随机访问”</p><p>但有利就有弊，这两个限制也让数组的很多操作变得非常低效，比如要想在数组中删除、插入一个数据，为了保证连续性，就需要做大量的数据搬移工作。</p><h2 id="_2-特性" tabindex="-1">2 特性 <a class="header-anchor" href="#_2-特性" aria-label="Permalink to &quot;2 特性&quot;">​</a></h2><h3 id="_2-1-随机访问" tabindex="-1">2.1 随机访问 <a class="header-anchor" href="#_2-1-随机访问" aria-label="Permalink to &quot;2.1 随机访问&quot;">​</a></h3><p>我们拿一个长度为 10 的 int 类型的数组 <code>int[] a = new int[10]</code> 来举例</p><p>计算机给数组 <code>a[10]</code>，分配了一块连续内存空间 1000 ～ 1039，其中，内存块的首地址为 <code>base_address = 1000</code></p><p><img src="'+r+`" alt=""></p><p>计算机会给每个内存单元分配一个地址，计算机通过地址来访问内存中的数据</p><p>当计算机需要随机访问数组中的某个元素时，它会首先通过下面的寻址公式，计算出该元素存储的内存地址：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>a[i]_address = base_address + i * data_type_size</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中 data_type_size 表示数组中每个元素的大小。我们举的这个例子里，数组中存储的是 int 类型数据，所以 data_type_size 就为 4 个字节</p><h3 id="_2-2-数组和链表的区别-随机访问" tabindex="-1">2.2 数组和链表的区别(随机访问) <a class="header-anchor" href="#_2-2-数组和链表的区别-随机访问" aria-label="Permalink to &quot;2.2 数组和链表的区别(随机访问)&quot;">​</a></h3><p>面试的时候，常常会问数组和链表的区别，很多人都回答说，“链表适合插入、删除，时间复杂度 O(1)；数组适合查找，查找时间复杂度为 O(1)”。</p><p>实际上，这种表述是不准确的。数组是适合查找操作，但是查找的时间复杂度并不为 O(1)。即便是排好序的数组，你用二分查找，时间复杂度也是 O(log n)。所以，正确的表述应该是，数组支持随机访问，根据下标随机访问的时间复杂度为 O(1)</p><h3 id="_2-3-低效的插入和删除" tabindex="-1">2.3 低效的插入和删除 <a class="header-anchor" href="#_2-3-低效的插入和删除" aria-label="Permalink to &quot;2.3 低效的插入和删除&quot;">​</a></h3><p>数组为了保持内存数据的连续性，会导致插入、删除这两个操作比较低效</p><h4 id="_1-插入" tabindex="-1">1 插入 <a class="header-anchor" href="#_1-插入" aria-label="Permalink to &quot;1 插入&quot;">​</a></h4><p>假设数组的长度为 n，现在，如果我们需要将一个数据插入到数组中的第 k 个位置。为了把第 k 个位置腾出来，给新来的数据，我们需要将第 k ～ n 这部分的元素都顺序地往后挪一位</p><p>如果在数组的末尾插入元素，那就不需要移动数据了，这时的时间复杂度为 O(1)。但如果在数组的开头插入元素，那所有的数据都需要依次往后移动一位，所以最坏时间复杂度是 O(n)。 因为我们在每个位置插入元素的概率是一样的，所以平均情况时间复杂度为 <code>(1 + 2 + … n) / n = O(n)</code></p><p>如果数组中的数据是有序的，我们在某个位置插入一个新的元素时，就必须按照刚才的方法搬移 k 之后的数据</p><h4 id="_2-删除" tabindex="-1">2 删除 <a class="header-anchor" href="#_2-删除" aria-label="Permalink to &quot;2 删除&quot;">​</a></h4><p>跟插入数据类似，如果我们要删除第 k 个位置的数据，为了内存的连续性，也需要搬移数据，不然中间就会出现空洞，内存就不连续了。</p><p>和插入类似，如果删除数组末尾的数据，则最好情况时间复杂度为 O(1)；如果删除开头的数据，则最坏情况时间复杂度为 O(n)；平均情况时间复杂度也为 O(n)。</p><h3 id="_2-4-数组的访问越界问题" tabindex="-1">2.4 数组的访问越界问题 <a class="header-anchor" href="#_2-4-数组的访问越界问题" aria-label="Permalink to &quot;2.4 数组的访问越界问题&quot;">​</a></h3><p>首先，分析一下这段 C 语言代码的运行结果：</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">int</span><span style="color:#6F42C1;"> main</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">int</span><span style="color:#E36209;"> argc</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">char*</span><span style="color:#E36209;"> argv</span><span style="color:#D73A49;">[]</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  int</span><span style="color:#24292E;"> i </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">  int</span><span style="color:#E36209;"> arr</span><span style="color:#24292E;">[</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">] </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> {</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">  for</span><span style="color:#24292E;"> (; i</span><span style="color:#D73A49;">&lt;=</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">; i</span><span style="color:#D73A49;">++</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#E36209;">    arr</span><span style="color:#24292E;">[i] </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6F42C1;">    printf</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;hello world</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>这段代码的运行结果并非是打印三行“hello word”，而是会无限打印“hello world”，这是为什么呢？</p><p>因为，数组大小为 3，<code>a[0]，a[1]，a[2]</code>，而我们的代码因为书写错误，导致 for 循环的结束条件错写为了 <code>i &lt;= 3</code> 而非 <code>i&lt;3</code>，所以当 i=3 时，数组 <code>a[3]</code> 访问越界。</p><p>在 C 语言中，只要不是访问受限的内存，所有的内存空间都是可以自由访问的。根据我们前面讲的数组寻址公式，<code>a[3]</code> 也会被定位到某块不属于数组的内存地址上，而这个地址正好是存储变量 i 的内存地址，那么 <code>a[3] = 0</code> 就相当于 <code>i=0</code>，所以就会导致代码无限循环。</p><p>数组越界在 C 语言中是一种未决行为，并没有规定数组访问越界时编译器应该如何处理。因为，访问数组的本质就是访问一段连续内存，只要数组通过偏移计算得到的内存地址是可用的，那么程序就可能不会报任何错误。</p><p>但并非所有的语言都像 C 一样，把数组越界检查的工作丢给程序员来做，像 Java 本身就会做越界检查，比如下面这几行 Java 代码，就会抛出 <code>java.lang.ArrayIndexOutOfBoundsException</code></p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">int</span><span style="color:#24292E;">[] a </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#D73A49;"> int</span><span style="color:#24292E;">[</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">];</span></span>
<span class="line"><span style="color:#24292E;">a[</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">] </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 10</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_3-js-中的数组" tabindex="-1">3 JS 中的数组 <a class="header-anchor" href="#_3-js-中的数组" aria-label="Permalink to &quot;3 JS 中的数组&quot;">​</a></h2><h3 id="_3-1-内部机制" tabindex="-1">3.1 内部机制 <a class="header-anchor" href="#_3-1-内部机制" aria-label="Permalink to &quot;3.1 内部机制&quot;">​</a></h3><p>数组是一种特殊的对象。使用方括号来访问属性 <code>arr[0]</code> 实际上是来自于对象的语法。它其实与 <code>obj[key]</code> 相同，其中 arr 是对象，而数字用作键（key）。</p><p>它们扩展了对象，提供了特殊的方法来处理有序的数据集合以及 length 属性。但从本质上讲，它仍然是一个对象</p><blockquote><p>数组真正特殊的是它们的内部实现。JavaScript 引擎尝试把这些元素一个接一个地存储在连续的内存区域，而且还有一些其它的优化，以使数组运行得非常快</p></blockquote><blockquote><p>如果我们不像“有序集合”那样使用数组，而是像常规对象那样使用数组，对应的优化就会被关闭</p></blockquote><p>数组误用的几种方式:</p><ol><li>添加一个非数字的属性，比如 <code>arr.test = 5</code></li><li>制造空洞，比如：添加 <code>arr[0]</code>，然后添加 <code>arr[1000]</code> (它们中间什么都没有)</li><li>以倒序填充数组，比如 <code>arr[1000]</code>，<code>arr[999]</code> 等</li></ol><h3 id="_3-2-性能" tabindex="-1">3.2 性能 <a class="header-anchor" href="#_3-2-性能" aria-label="Permalink to &quot;3.2 性能&quot;">​</a></h3><p>push/pop 方法运行的比较快，而 shift/unshift 比较慢</p><p>shift 操作必须做三件事:</p><ol><li>移除索引为 0 的元素</li><li>把所有的元素向左移动，把索引 1 改成 0，2 改成 1 以此类推，对其重新编号</li><li>更新 length 属性</li></ol><h3 id="_3-3-length" tabindex="-1">3.3 length <a class="header-anchor" href="#_3-3-length" aria-label="Permalink to &quot;3.3 length&quot;">​</a></h3><p>length 实际上不是数组里元素的个数，而是最大的数字索引值加一</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> fruits </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [];</span></span>
<span class="line"><span style="color:#24292E;">fruits[</span><span style="color:#005CC5;">123</span><span style="color:#24292E;">] </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;Apple&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">alert</span><span style="color:#24292E;">(fruits.</span><span style="color:#005CC5;">length</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// 124</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>length 可更改，增加 length 不会有什么影响。减少 length 数组会被截断，并且是不可逆的</p></blockquote>`,59)])])}const m=s(t,[["render",c]]);export{_ as __pageData,m as default};
